/*
 * A103705  Add 6 to each of the preceding digits, beginning with 1.
 * https://oeis.org/A103705
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn
 * Formula:   not stated
 * Range:     u8 n <= 87, u16 n <= 87, u32 n <= 87, u64 n <= 87, u128 n <= 87,
 *            big any n
 * Helpers:   free_seq_array, push_seq, seq_malloc, seq_to_dec_string
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Implementation: breadth‑first traversal of the tree generated by
   adding 6 to each decimal digit of a number.  a(1)=1 is the root,
   and the children of a node are produced in the order of its decimal
   digits from left to right.  The function returns the n‑th visited
   node (1‑based indexing).  The algorithm uses a dynamic queue handled
   with the utility functions provided in the build. */
#include <stdbool.h>
#include "../utils/seq_malloc.h"
#include "../utils/free_seq_array.h"
#include "../utils/seq_to_dec_string.h"
#include "../utils/push_seq.h"

seq_t a(idx_t n)
{
    /*  The queue is kept static so repeated calls reuse the
        already generated part of the traversal.  */
    static seq_t *queue      = NULL;
    static idx_t  cap        = 0;
    static idx_t  size       = 0;   // number of elements in the queue
    static idx_t  front      = 0;   // index of next element to process
    static bool   initialized = false;

    if (!initialized) {
        /*  Start with a capacity of 1024; it will grow automatically
            by push_seq when needed.  */
        cap = 1024;
        queue = seq_malloc(cap);
        if (!queue) return (seq_t)0; /* allocation failure – unlikely */

        /*  Insert the root node (value 1).  */
        push_seq(&queue, &cap, &size, (seq_t)1);
        initialized = true;
    }

    /*  Generate nodes until we have at least n of them.  */
    while (size < n) {
        seq_t val = queue[front];   /*  current node  */

        /*  Produce its children: for each decimal digit d,
            the child is (d+6).  */
        char buf[128];
        seq_to_dec_string(val, buf, sizeof buf);
        for (char *p = buf; *p; ++p) {
            if (*p < '0' || *p > '9') continue;
            seq_t child = (seq_t)(*p - '0') + 6;
            push_seq(&queue, &cap, &size, child);
        }
        front++;   /*  move to the next node in the queue  */
    }

    return queue[n - 1];
}
